// HEAP przechowuje WSZYSTKIE obiekty utworzone przez 'new' - zarzadza nim Garbage Collector,
// ktory automatycznie zwalnia pamiec nieuzywanych juz obiektow.
// STACK to OGRANICZONY, dedykowany kazdemu WATKOWI obszar pamieci przechowujacy ramki
// wywolan metod (zmienne lokalne, adresy powrotu) - zarzadzany PROSTO, mechanizmem
// LIFO (stos), przez sam watek, bez udzialu GC - ramka jest automatycznie usuwana przy
// wyjsciu z metody.
// METASPACE przechowuje METADANE KLAS (bajtkod metod, constant pool) - rosnie w pamieci
// natywnej, POZA zwykla stertą, i jest posrednio zarzadzany przez cykl zycia class loaderow
// (Lekcja 4) - klasa jest usuwana z metaspace dopiero, gdy caly jej loader stanie sie
// nieosiagalny dla GC.

MemoryMXBean bean = ManagementFactory.getMemoryMXBean();
MemoryUsage heap = bean.getHeapMemoryUsage();
System.out.println("init: " + heap.getInit());
System.out.println("used: " + heap.getUsed());
System.out.println("committed: " + heap.getCommitted());
System.out.println("max: " + heap.getMax());

MemoryUsage nonHeap = ManagementFactory.getMemoryMXBean().getNonHeapMemoryUsage();
System.out.println("init: " + nonHeap.getInit());
System.out.println("used: " + nonHeap.getUsed());
System.out.println("committed: " + nonHeap.getCommitted());
System.out.println("max: " + nonHeap.getMax());

for (MemoryPoolMXBean pool : ManagementFactory.getMemoryPoolMXBeans()) {
    System.out.println("- " + pool.getName());
}

for (MemoryPoolMXBean pool : ManagementFactory.getMemoryPoolMXBeans()) {
    if (pool.getType() == java.lang.management.MemoryType.HEAP) {
        System.out.println(pool.getName());
    }
}

private static void recurseInfinite() { recurseInfinite(); }

try {
    recurseInfinite();
} catch (StackOverflowError e) {
    System.out.println("Stos przepelniony!");
}

static long depth = 0;
static void recurseCounted() { depth++; recurseCounted(); }

try {
    recurseCounted();
} catch (StackOverflowError e) {
    System.out.println("Osiagnieta glebokosc: " + depth);
}

// -Xss ustawia rozmiar stosu KAZDEGO nowego watku JVM (np. -Xss128k = 128 kilobajtow na watek).
// Zmniejszenie -Xss do 128k dla kodu z Zadania 7/8 sprawi, ze StackOverflowError wystapi
// PRZY MNIEJSZEJ GLEBOKOSCI rekurencji niz przy domyslnym rozmiarze stosu - mniej pamieci
// oznacza mniej miejsca na kolejne ramki wywolan, wiec 'limit' zostanie osiagniety szybciej.

// PermGen (Java < 8) byl CZESCIA sterty, z domyslnie MALYM, STALYM rozmiarem - czesta
// przyczyna OutOfMemoryError: PermGen space w starszych aplikacjach z wieloma klasami
// (np. generowanymi dynamicznie przez frameworki). Od Javy 8, Metaspace zastapil PermGen -
// zyje w pamieci NATYWNEJ procesu (poza sterta), domyslnie BEZ zadnego limitu, ograniczony
// tylko dostepna pamiecia systemu operacyjnego.
// Przekroczenie jawnie ustawionego -XX:MaxMetaspaceSize powoduje kontrolowany
// OutOfMemoryError: Metaspace, zamiast pozwolic procesowi zuzyc CALA pamiec systemu.

MemoryUsage heap = ManagementFactory.getMemoryMXBean().getHeapMemoryUsage();
double percent = heap.getUsed() * 100.0 / heap.getCommitted();
System.out.printf("Zajetosc heap: %.2f%%%n", percent);

MemoryPoolMXBean max = ManagementFactory.getMemoryPoolMXBeans().stream()
    .max(java.util.Comparator.comparingLong(p -> p.getUsage().getUsed()))
    .orElseThrow();
System.out.println(max.getName() + ": " + max.getUsage().getUsed() + " B");

for (MemoryPoolMXBean pool : ManagementFactory.getMemoryPoolMXBeans()) {
    MemoryUsage u = pool.getUsage();
    if (u.getMax() >= 0) {
        System.out.println(pool.getName() + ": moze urosnac o " + (u.getMax() - u.getInit()) + " B");
    }
}

for (int i = 0; i < 3; i++) {
    depth = 0;
    try { recurseCounted(); } catch (StackOverflowError e) { System.out.println("Proba " + i + ": " + depth); }
}
// Glebokosc MOZE nieznacznie sie roznic miedzy uruchomieniami - zalezy od aktualnego stanu
// stosu (inne watki/inne wczesniejsze wywolania), optymalizacji JIT i chwilowego obciazenia
// systemu - to NIE jest stala, deterministyczna wartosc.

static long d2 = 0;
static void recurseWithVars() {
    d2++;
    long a=1,b=2,c=3,e=4,f=5,g=6,h=7,i=8,j=9,k=10,l=11,m=12,n=13,o=14,p=15,q=16,r=17,s=18,t=19,u=20;
    recurseWithVars();
}
// Metoda z wieloma zmiennymi lokalnymi ma WIEKSZA ramke stosu na wywolanie - przy TYM SAMYM
// rozmiarze stosu (-Xss) osiagnie MNIEJSZA maksymalna glebokosc rekurencji niz metoda
// bezargumentowa/bez dodatkowych zmiennych z Zadania 7.

static long sum(int n) { return n <= 0 ? 0 : n + sum(n - 1); }
try {
    System.out.println("Suma 1..10000 = " + sum(10000));
} catch (StackOverflowError e) {
    System.out.println("StackOverflowError dla n=10000");
}

long before = ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getUsed();
int[] big = new int[10_000_000];
long after = ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getUsed();
System.out.println("Przed: " + before + ", po: " + after + ", roznica: " + (after - before) + " B");
// Tablica 10 mln intow zajmuje ~40MB (4 bajty na element) - 'used' powinno wzrosnac
// o w przyblizeniu te wartosc, chyba ze GC zdazyl posprzatac cos innego w miedzyczasie.

long heapCount = ManagementFactory.getMemoryPoolMXBeans().stream().filter(p -> p.getType() == java.lang.management.MemoryType.HEAP).count();
long nonHeapCount = ManagementFactory.getMemoryPoolMXBeans().stream().filter(p -> p.getType() == java.lang.management.MemoryType.NON_HEAP).count();
System.out.println("HEAP: " + heapCount + ", NON_HEAP: " + nonHeapCount);

// Kazdy watek MUSI miec wlasny, niezalezny stos, bo stos reprezentuje AKTUALNY 'lancuch
// wywolan' TEGO KONKRETNEGO watku - jego lokalne zmienne, adresy powrotu z metod. Gdyby
// watki dzielily JEDEN wspolny stos, dwa watki wywolujace metody RÓWNOLEGLE (patrz
// _05_multithreading) natychmiast 'nadpisywalyby' sobie nawzajem ramki wywolan -
// zmienna lokalna jednego watku zostalaby przypadkowo odczytana/nadpisana przez drugi,
// dajac calkowicie nieprzewidywalne, chaotyczne zachowanie. Osobny stos per watek to
// fundament bezpiecznej, niezaleznej egzekucji kodu w wielu watkach naraz.

static void printMemoryReport() {
    MemoryMXBean bean = ManagementFactory.getMemoryMXBean();
    System.out.println("Heap used/max: " + bean.getHeapMemoryUsage().getUsed() + "/" + bean.getHeapMemoryUsage().getMax());
    System.out.println("Non-heap used/max: " + bean.getNonHeapMemoryUsage().getUsed() + "/" + bean.getNonHeapMemoryUsage().getMax());
    System.out.println("Liczba pul pamieci: " + ManagementFactory.getMemoryPoolMXBeans().size());
}
printMemoryReport();

List<byte[]> kept = new ArrayList<>();
for (int i = 0; i < 5; i++) {
    for (int j = 0; j < 1_000_000; j++) kept.add(new byte[16]);
    System.out.println("Iteracja " + i + ": used=" + ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getUsed());
}

static long probeDepth = 0;
static void probeRecurse() { probeDepth++; probeRecurse(); }
static long probeMaxDepth() {
    probeDepth = 0;
    try { probeRecurse(); } catch (StackOverflowError e) { }
    return probeDepth;
}

System.out.println("Proba 1: " + probeMaxDepth());
System.out.println("Proba 2: " + probeMaxDepth());

static long depthA = 0, depthB = 0;
static void recurseA() { depthA++; recurseA(); }
static void recurseB() { depthB++; long[] buffer = new long[50]; recurseB(); }

try { recurseA(); } catch (StackOverflowError e) { }
try { recurseB(); } catch (StackOverflowError e) { }
System.out.println("Bez zmiennych: " + depthA + ", z tablica[50]: " + depthB + " (oczekiwane: B < A)");

long before = ManagementFactory.getMemoryPoolMXBeans().stream().filter(p -> p.getName().contains("Metaspace")).findFirst().map(p -> p.getUsage().getUsed()).orElse(0L);
// zaladuj 30 roznych, dynamicznie generowanych klas przez custom ClassLoader (Lekcja 4)
long after = ManagementFactory.getMemoryPoolMXBeans().stream().filter(p -> p.getName().contains("Metaspace")).findFirst().map(p -> p.getUsage().getUsed()).orElse(0L);
System.out.println("Metaspace przed: " + before + ", po: " + after + " - kazda nowa klasa zajmuje metadane");

long mainThreadDepth = probeMaxDepth();
long[] threadDepth = new long[1];
Thread t = new Thread(null, () -> { probeDepth = 0; try { probeRecurse(); } catch (StackOverflowError e) { } threadDepth[0] = probeDepth; }, "BigStack", 8 * 1024 * 1024);
t.start();
t.join();
System.out.println("Glowny watek: " + mainThreadDepth + ", watek z 8MB stosu: " + threadDepth[0]);

static void diffMemory(Runnable action) {
    Map<String, Long> before = snapshot();
    action.run();
    Map<String, Long> after = snapshot();
    for (String pool : before.keySet()) {
        long diff = after.get(pool) - before.get(pool);
        if (diff != 0) System.out.println(pool + ": " + (diff > 0 ? "+" : "") + diff + " B");
    }
}
static Map<String, Long> snapshot() {
    Map<String, Long> m = new HashMap<>();
    for (MemoryPoolMXBean p : ManagementFactory.getMemoryPoolMXBeans()) m.put(p.getName(), p.getUsage().getUsed());
    return m;
}

diffMemory(() -> { List<byte[]> l = new ArrayList<>(); for (int i = 0; i < 100_000; i++) l.add(new byte[64]); });

// Scenariusz: sklep internetowy przechowuje drzewo KATEGORII produktow (np. Elektronika ->
// Komputery -> Laptopy -> Gamingowe), gdzie kazda kategoria moze miec podkategorie. Metoda
// rekurencyjna 'obliczCalkowitaLiczbeProduktow(Kategoria k)' sumuje produkty ze wszystkich
// podkategorii rekurencyjnie. Jesli administrator (przypadkowo lub celowo) utworzy BARDZO
// glebokie drzewo (np. tysiace zagniezdzonych podkategorii przez blad w panelu admina,
// albo import danych z zewnetrznego zrodla bez walidacji glebokosci), metoda rekurencyjna
// moze przekroczyc rozmiar stosu i rzucic StackOverflowError NA PRODUKCJI, przy realnym
// zadaniu klienta.
// Rozwiazanie 1: przepisac algorytm na ITERACYJNY, uzywajac wlasnego stosu (java.util.Deque)
// zamiast rekurencji jezyka - eliminuje ograniczenie rozmiaru stosu JVM calkowicie.
// Rozwiazanie 2: dodac JAWNY LIMIT GLEBOKOSCI rekurencji (np. parametr 'int maxDepth')
// i rzucic czytelny, wlasny wyjatek biznesowy, gdy limit zostanie przekroczony - zamiast
// pozwolic na niekontrolowany StackOverflowError.

static long sumRecursive(int n) { return n <= 0 ? 0 : n + sumRecursive(n - 1); }
static long sumIterative(int n) {
    long sum = 0;
    for (int i = 1; i <= n; i++) sum += i;
    return sum;
}

try {
    System.out.println(sumRecursive(10_000_000)); // prawdopodobnie StackOverflowError
} catch (StackOverflowError e) {
    System.out.println("Rekurencyjna: StackOverflowError");
}
System.out.println("Iteracyjna: " + sumIterative(10_000_000)); // dziala bez problemu

System.out.println("=== PELNY RAPORT DIAGNOSTYCZNY JVM ===");
MemoryMXBean bean = ManagementFactory.getMemoryMXBean();
System.out.println("Heap: used=" + bean.getHeapMemoryUsage().getUsed() + ", max=" + bean.getHeapMemoryUsage().getMax());
System.out.println("Non-heap: used=" + bean.getNonHeapMemoryUsage().getUsed() + ", max=" + bean.getNonHeapMemoryUsage().getMax());

System.out.println("--- Pule pamieci ---");
for (MemoryPoolMXBean pool : ManagementFactory.getMemoryPoolMXBeans()) {
    MemoryUsage u = pool.getUsage();
    double percent = u.getMax() > 0 ? u.getUsed() * 100.0 / u.getMax() : -1;
    System.out.printf("%s: %.2f%%%n", pool.getName(), percent);
}

System.out.println("--- Proba glebokiej rekurencji ---");
System.out.println("Osiagnieta glebokosc: " + probeMaxDepth());
